//go:build integration

package health_test

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/mbashem/cftracker/backend/internal/health"
	"github.com/mbashem/cftracker/backend/internal/routes"
	testutil "github.com/mbashem/cftracker/backend/tests/support"
)

// Generated by Codex and not thoroughly checked for correctness.
func TestHealthWithPostgres(t *testing.T) {
	gin.SetMode(gin.TestMode)
	database := testutil.OpenTestDB(t)
	database.SetMaxOpenConns(1)
	router := gin.New()
	routes.RegisterRoutes(router, routes.Dependencies{Health: health.NewAPI(database)})
	check := func(path string, wantStatus int) {
		t.Helper()
		response := httptest.NewRecorder()
		router.ServeHTTP(response, httptest.NewRequestWithContext(t.Context(), http.MethodGet, path, nil))
		if response.Code != wantStatus {
			t.Fatalf("GET %s status = %d, want %d; body = %s", path, response.Code, wantStatus, response.Body.String())
		}
	}

	check("/health/ready", http.StatusOK)
	connection, err := database.Conn(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { connection.Close() })
	// Holding the only connection makes readiness wait for its own deadline.
	check("/health/live", http.StatusOK)
	check("/health/ready", http.StatusServiceUnavailable)
	if err := connection.Close(); err != nil {
		t.Fatal(err)
	}
	check("/health/ready", http.StatusOK)
	if err := database.Close(); err != nil {
		t.Fatal(err)
	}
	check("/health/ready", http.StatusServiceUnavailable)
	check("/health/live", http.StatusOK)
}
